import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue accessing URL: {e}")

    try:
        tables = pd.read_html(response.text)
        if not tables:
            return 0
        df = tables[0]
        if df.empty:
            return 0
    except ValueError:
        return 0

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return len(df)

import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.RequestException:
        return []

    soup = BeautifulSoup(response.text, 'html.parser')
    result = []
    for tag in soup.find_all('script'):
        if tag.string:
            try:
                parsed = ast.literal_eval(tag.string)
                if isinstance(parsed, dict):
                    result.append(parsed)
            except (ValueError, SyntaxError):
                pass
    return result

import requests
import logging
def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url)
        response.raise_for_status()
        repo_info = response.json()
    except requests.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}") from e
    except requests.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}") from e

    if repo_info.get('open_issues_count', 0) > 1000:
        logging.warning(f"Large number of open issues: {repo_info['open_issues_count']}")

    return repo_info

